"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95971"],{43862(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.estrutura_invalida","status":422,"titulo":"As regras n\xe3o formam um formul\xe1rio: elemento nulo, c\xf3digo repetido ou refer\xeancia que n\xe3o existe"},"descricao":{"codigo":"uniplus.formulario_portavel.estrutura_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. As regras recebidas t\xeam um defeito de estrutura que impede formar o formul\xe1rio. Os casos s\xe3o estes, cada um com a pr\xf3pria mensagem: um elemento nulo dentro de uma lista, como \\"O elemento das regras \xe9 nulo.\\", com o caminho do elemento no campo, por exemplo `paginas[0].itens[2]`; uma p\xe1gina, um grupo, um campo, um termo, um resumo de grupo ou uma deriva\xe7\xe3o sem c\xf3digo; um c\xf3digo repetido, como \\"O c\xf3digo \'`{c\xf3digo\\\\}`\' aparece mais de uma vez como p\xe1gina.\\", e do mesmo modo entre termos e entre fatos produzidos ou grupos do formul\xe1rio (campos, deriva\xe7\xf5es, resumos de grupo e grupos dividem o mesmo conjunto de c\xf3digos); os limites de ocorr\xeancias de um grupo incoerentes, com m\xednimo negativo, ou m\xe1ximo informado menor que 1 ou menor que o m\xednimo; um formato de texto que n\xe3o \xe9 do vocabul\xe1rio do cat\xe1logo; e um resumo sobre um grupo que o formul\xe1rio n\xe3o tem.","A recusa vem na lista `errors` da resposta, uma entrada por recusa, cada uma com `field` igual ao caminho do elemento recusado nas regras enviadas, por exemplo `paginas[0].itens[2]`, ou mais fundo quando a recusa \xe9 de uma parte dele. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, nesta ordem: as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto, e todas as recusas de uma mesma etapa voltam juntas. A confer\xeancia do conjunto (c\xf3digo repetido, refer\xeancia a algo que o formul\xe1rio n\xe3o tem) s\xf3 vem depois que nenhum elemento foi recusado, e \xe9 a \xfanica recusa sem `field`. Havendo defeito de estrutura do documento (elemento nulo numa lista ou grupo sem `ocorrencias`), s\xf3 as recusas de estrutura voltam, cada uma no caminho do elemento, e nada mais \xe9 lido.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Corrija o trecho indicado na mensagem nas regras enviadas e repita a avalia\xe7\xe3o. Um c\xf3digo repetido se resolve dando c\xf3digos distintos, e o limite de ocorr\xeancias de um grupo deve ter m\xednimo de zero para cima e, quando houver m\xe1ximo, ele deve ser pelo menos 1 e n\xe3o menor que o m\xednimo."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);